using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ReshapeAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Reshape Action")]
public class ReshapeAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private BattleAction actionToTransfigure;

	[SerializeField]
	private int actionValue;

	public BattleAction ActionToTransfigure => actionToTransfigure;

	public int ActionValue => actionValue;

	public override void AreaCastTarget(List<GameObject> targets, GameObject source)
	{
		for (int i = 0; i < targets.Count; i++)
		{
			CastTarget(targets[i], source);
		}
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		target.GetComponent<SpriteControl>().OnBlink();
		List<DiceInstance> list = target.GetComponent<UnitsDiceActivation>().TransfigureDiceFace(actionToTransfigure, actionValue);
		if (IsVFXEnabled())
		{
			PlaySFX();
			for (int i = 0; i < list.Count; i++)
			{
				GetVFX(4f).GetComponent<ParticleFollower>().Initialize(list[i]);
			}
		}
	}
}
